<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';
try{$uid=(int)requireAuth()->id;$periodId=(int)($_GET['period_id']??0);$c=db();requirePermission($c,$uid,'accounting.periods.manage');$s=$c->prepare('SELECT s.id,s.version,s.status,s.snapshot_json,s.snapshot_sha256,s.captured_by,s.captured_at FROM erp_accounting_period_snapshots s JOIN erp_accounting_periods p ON p.id=s.period_id WHERE s.period_id=? AND s.user_id=? AND p.user_id=? ORDER BY s.version DESC');$s->bind_param('iii',$periodId,$uid,$uid);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();foreach($rows as &$row){$row['snapshot']=json_decode($row['snapshot_json'],true);unset($row['snapshot_json']);}unset($row);jsonResponse(['success'=>true,'data'=>$rows]);}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>$e->getMessage()],400);}
